SELECT COALESCE(SUM(CASE WHEN type = 'income' THEN amount ELSE -amount END), 0)
FROM `transaction`
WHERE book_id = #{bookId}
  AND deleted = 0
  AND id != #{excludeId}

SELECT COALESCE(SUM(CASE WHEN type = 'income' THEN amount ELSE -amount END), 0)
FROM `transaction`
WHERE book_id = #{bookId}
  AND deleted = 0
  AND trans_date <= #{date}
